INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "獣人族", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助けが大好き！　前向き格闘娘", 16, 0, 2, 100101, 27, "人助け、応援", "トゥインクルウィッシュ", 155, "東山奈央", 44, "ヒヨリ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, "ヒューマン", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "戦闘のサポートが得意な、心優しい少女", 17, 0, 2, 100201, 5, "料理、人間観察", "トゥインクルウィッシュ", 158, "種田梨沙", 47, "ユイ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, "魔族", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "クールで何事にも真っ直ぐな剣士", 18, 0, 2, 100301, 12, "読書、乗馬、お茶", "トゥインクルウィッシュ", 163, "早見沙織", 46, "レイ", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "ヒューマン", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "探検好きのイタズラっ子", 9, 0, 5, 100401, 10, "いたずら、探検", "リトルリリカル", 128, "諸星すみれ", 27, "ミソギ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "獣人族", "？？？", "ヒーローに憧れる騎士見習いの少女", 12, 0, 8, 100501, 25, "ヒーローごっこ", "王宮騎士団（NIGHTMARE）", 146, "下田麻美", 40, "マツリ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "魔族", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "甘え上手なみんなの人気者", 13, 0, 7, 100601, 22, "サックス", "悪魔偽王国軍（ディアボロス）", 150, "浅倉杏美", 42, "アカリ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, "魔族", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "プリン大好きゴースト娘", 14, 0, 7, 100701, 23, "プリンを食べること", "悪魔偽王国軍（ディアボロス）", 130, "雨宮天", 32, "ミヤコ", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, "エルフ", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "ボクは誰よりも美しい", 14, 0, 15, 100801, 10, "鏡で自分を見ること", "ヴァイスフリューゲル　ランドソル支部", 150, "大空直美", 40, "ユキ", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "魔族", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "前世を信じる中二病患者、「疾風の冥姫」", 17, 0, 13, 100901, 5, "小説執筆", "トワイライトキャラバン", 159, "髙野麻美", 45, "アンナ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "獣人族", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "マホマホ王国のプリンセス", 16, 0, 10, 101001, 22, "空想、ぬいぐるみ集め", "自警団（カォン）", 155, "内田真礼", 42, "マホ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "ヒューマン", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "人懐っこくてマシンガントークな妹系少女", 15, 0, 3, 101101, 25, "お裁縫", "ラビリンス", 156, "阿澄佳奈", 44, "リノ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, "エルフ", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "みんなのために超能力を使う眠り姫", 17, 0, 6, 101201, 24, "妹と遊ぶこと、二度寝、昼寝、早寝", "フォレスティエ", 156, "大橋彩香", 46, "ハツネ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "魔族", "", "オタク全開な魔法少女", 18, 0, 13, 101301, 21, "読書、魔法", "トワイライトキャラバン", 166, "佳村はるか", 55, "ナナカ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "獣人族", "test", "頭脳明晰な美少女名探偵", 15, 0, 10, 101401, 3, "読書、推理", "自警団（カォン）", 152, "水瀬いのり", 41, "カスミ", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "エルフ", "test", "母性溢れる優しいみんなの「ミサト先生」", 21, 0, 6, 101501, 5, "絵本作り", "フォレスティエ", 165, "國府田マリ子", 54, "ミサト", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, "魔族", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "天真爛漫で人気者のカリスマモデル", 17, 0, 14, 101601, 10, "ファッション", "ルーセント学院", 167, "上坂すみれ", 48, "スズナ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "獣人族", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "いつでも「なんくるないさ～」な天然娘", 17, 0, 10, 101701, 7, "踊り、空手", "自警団（カォン）", 158, "高森奈津美", 53, "カオリ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "魔族", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "多くの男性を魅了する無垢な女教師", 23, 0, 14, 101801, 14, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "ルーセント学院", 162, "伊藤静", 52, "イオ", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, "獣人族", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "お歌もにんじんも、ウサギさんも大好き♪", 10, 0, 5, 102001, 3, "かわいいもの集め", "リトルリリカル", 117, "日高里菜", 21, "ミミ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, "ヒューマン", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "泣き虫で臆病な守ってあげたい女の子", 12, 0, 9, 102101, 9, "観劇、おままごと", "サレンディア救護院", 150, "植田佳奈", 40, "クルミ", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "魔族", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "人見知りであまのじゃくな女の子", 13, 0, 7, 102201, 22, "ゲーム全般", "悪魔偽王国軍（ディアボロス）", 150, "原紗友里", 40, "ヨリ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, "ヒューマン", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "ぷうきちといつも一緒！", 14, 0, 9, 102301, 10, "屋内でできる遊び", "サレンディア救護院", 148, "芹澤優", 38, "アヤネ", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, "ヒューマン", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "お嬢さまのためにがんばるドジっ娘メイド", 15, 0, 9, 102501, 12, "ご奉仕", "サレンディア救護院", 154, "悠木碧", 43, "スズメ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, "獣人族", "test", "遊びと睡眠が何より大事なぐうたら娘", 17, 0, 11, 102601, 1, "あんパン", "牧場（エリザベスパーク）", 144, "小岩井ことり", 42, "リン", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "魔族", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "運命の相手に一途すぎる乙女", 16, 0, 13, 102701, 30, "実験、裁縫、料理", "トワイライトキャラバン", 154, "橋本ちなみ", 43, "エリコ", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, "エルフ", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "救護院を経営する優しい庶民派お嬢様", 17, 0, 9, 102801, 4, "経営、お茶会", "サレンディア救護院", 156, "堀江由衣", 43, "サレン", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, "ヒューマン", "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", "歌って踊れる大人気アイドル", 17, 0, 4, 102901, 24, "舞台鑑賞、ダンス", "カルミナ", 157, "日笠陽子", 40, "ノゾミ", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "ヒューマン", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "トーゴクの神秘、オシエテクダサイ！", 16, 0, 15, 103001, 31, "忍法開発", "ヴァイスフリューゲル　ランドソル支部", 163, "佐藤聡美", 51, "ニノン", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, "魔族", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占いが得意な霊能少女", 18, 0, 7, 103101, 22, "占い", "悪魔偽王国軍（ディアボロス）", 157, "大坪由佳", 42, "シノブ", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "ヒューマン", "この私とともにいる限り、\nお金に不自由はさせませんわ！", "一人前の商人を目指すパワフルお嬢様", 18, 0, 12, 103201, 12, "慈善事業", "メルクリウス財団", 157, "松嵜麗", 45, "アキノ", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "ヒューマン", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "みんなを笑顔にするお笑い牧場主", 20, 0, 11, 103301, 3, "漫才", "牧場（エリザベスパーク）", 142, "新田恵海", 35, "マヒル", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "エルフ", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "純情でほっとけない大人の女性", 22, 0, 12, 103401, 16, "ウインドーショッピング", "メルクリウス財団", 164, "今井麻美", 55, "ユカリ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (2, "エルフ", "test", "礼儀正しくしっかり者のちびっ子優等生", 8, 0, 5, 103601, 2, "お勉強", "リトルリリカル", 118, "小倉唯", 21, "キョウカ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "ヒューマン", "test", "義理堅くてからかい好きな剣術少女", 13, 0, 8, 103701, 11, "剣術、年長者をからかう", "王宮騎士団（NIGHTMARE）", 149, "茅原実里", 43, "トモ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "獣人族", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "読書が趣味の病弱少女", 14, 0, 11, 103801, 3, "読書、お散歩", "牧場（エリザベスパーク）", 153, "小清水亜美", 40, "シオリ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, "エルフ", "友達ができるその日まで…\nBB団で\nトレーニングですっ！", "「友達」に憧れる、エルフの森の女の子", 13, 0, 6, 104001, 6, "友達作りのイメトレ", "フォレスティエ", 158, "花澤香菜", 44, "アオイ", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, "ヒューマン", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "人々を守るために歌う、唱喚士の少女", 17, 0, 4, 104201, 3, "各種楽器", "カルミナ", 163, "福原綾香", 46, "チカ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "獣人族", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "男勝りで情に厚いワイルド娘", 17, 0, 10, 104301, 9, "お菓子作り", "自警団（カォン）", 168, "小松未可子", 54, "マコト", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, "魔族", "test", "かつては夜を支配した最強の吸血鬼", "??", 0, 7, 104401, 5, "世界征服", "悪魔偽王国軍（ディアボロス）", 172, "丹下桜", 50, "イリヤ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "ヒューマン", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "妄想大好き！　ほんとは照れ屋な女の子", 18, 0, 15, 104501, 19, "小説を読むこと", "ヴァイスフリューゲル　ランドソル支部", 157, "長妻樹里", 49, "クウカ", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "獣人族", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "弱きを助け強きをくじく猫娘", 19, 0, 12, 104601, 1, "猫とたわむれること", "メルクリウス財団", 158, "沼倉愛美", 48, "タマキ", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, "ヒューマン", "？？？", "素顔を見せない冷静沈着な女性騎士", 25, 0, 8, 104701, 25, "格闘技、湯浴み", "王宮騎士団（NIGHTMARE）", 171, "川澄綾子", 50, "ジュン", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "ヒューマン", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "仕事も私事も効率優先な傭兵少女", 20, 0, 12, 104801, 11, "傭兵などのアルバイト", "メルクリウス財団", 163, "田所あずさ", 49, "ミフユ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, "ヒューマン", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "お姉ちゃんがお世話してあげるからねっ！", 18, 0, 3, 104901, 24, "家事全般", "ラビリンス", 168, "生天目仁美", 54, "シズル", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, "魔族", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ちょっとおませな恋に恋する女の子", 11, 0, 14, 105001, 3, "ファッション誌鑑賞、コスメ集め", "ルーセント学院", 120, "久野美咲", 22, "ミサキ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "ヒューマン", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "実験が趣味の危険な科学者", 27, 0, 13, 105101, 7, "研究、実験", "トワイライトキャラバン", 166, "三石琴乃", 53, "ミツキ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "獣人族", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "乙女チックなもふもふアニマル", 17, 0, 11, 105201, 14, "毛繕い、お喋り", "牧場（エリザベスパーク）", 150, "徳井青空", 100, "リマ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "ヒューマン", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "見た目も中身もお子ちゃまな異国の軍人", 17, 0, 15, 105301, 28, "お菓子屋通い", "ヴァイスフリューゲル　ランドソル支部", 140, "辻あゆみ", 33, "モニカ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "ヒューマン", "test", "ファッション大好きなキュートガール", 14, 0, 4, 105401, 7, "裁縫", "カルミナ", 153, "木戸衣吹", 45, "ツムギ", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, "エルフ", "test", "どこまでも一途に慕う、純情乙女", 16, 0, 15, 105501, 7, "観察", "ヴァイスフリューゲル　ランドソル支部", 155, "大関英里", 43, "アユミ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "ヒューマン", "test", "人情味溢れる粋でいなせな「姉御」", 25, 0, 13, 105601, 11, "釣り", "トワイライトキャラバン", 167, "佐藤利奈", 54, "ルカ", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "ヒューマン", "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", "空への冒険を夢見る騎空士の少女", 17, 0, "", 105701, 10, "冒険、おしゃべり", "？？？", 156, "金元寿子", 45, "ジータ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "ヒューマン", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "いつも元気な腹ペコ少女", 17, 0, 1, 105801, 31, "食べ歩き、料理", "美食殿", 156, "M・A・O", 46, "ペコリーヌ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, "エルフ", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "主を慕う、小さなガイド役", 11, 0, 1, 105901, 11, "瞑想、動植物の飼育", "美食殿", 140, "伊藤美来", 35, "コッコロ", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "獣人族", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "行き倒れの謎のネコミミ魔法使い", 14, 0, 1, 106001, 2, "猫と遊ぶ", "美食殿", 152, "立花理香", 39, "キャル", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "ヒューマン", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "さまよえる謎の少女", 16, 0, "", 106101, 11, "冒険、思い出話", "？？？", 148, "潘めぐみ", 40, "ムイミ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, "エルフ", "", "森番を目指すエルフの少女", 15, 0, "", 106301, 17, "キレイな葉っぱを集めること", "？？？", 155, "優木かな", 42, "アリサ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, "ドラゴン族", "", "記憶喪失のドラゴン娘", 14, 0, 1, 106401, 14, "読書、ストレッチ", "美食殿", 147, "近藤玲奈", "???", "シェフィ", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, "ドラゴン族", "", "拳で語る喧嘩屋ドラゴン少女", 16, 0, 17, 106501, 25, "格闘技", "ドラゴンズネスト", 156, "小市眞琴", "???", "カヤ", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "ドラゴン族", "", "口が達者なヘタレドラゴン", 13, 0, 17, 106601, 29, "ゲーム", "ドラゴンズネスト", 145, "藤田茜", "???", "イノリ", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, "ドラゴン族", "", "妖しい微笑で全てを見透かす臥竜の頭領", 25, 0, 17, 106701, 17, "絵画、読書", "ドラゴンズネスト", 168, "大西沙織", "???", "ホマレ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "ヒューマン", "", "秘密結社ラビリンスの『迷宮女王』", 25, 0, 3, 106801, 25, "人間観察", "ラビリンス", 160, "沢城みゆき", "??", "ラビリスタ", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "獣人族", "", "謎に包まれたランドソルの主", 29, 0, "", 106901, 1, "占い、支配", "？？？", 166, "蒼井翔太", "??", "カイザーインサイト", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "エルフ", "", "研究所に隠れ住む物静かなお姉さん", 24, 0, "", 107001, 24, "物真似、芸術鑑賞", "？？？", 149, "井口裕香", "??", "ネネカ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (2, "ヒューマン", "", "傍若無人な王宮騎士団副団長", 27, 0, 8, 107101, 7, "強敵との闘争", "王宮騎士団（NIGHTMARE）", 165, "たかはし智秋", "??", "クリスティーナ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "ヒューマン", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "いつも元気な腹ペコ少女", 17, 0, 1, 107501, 31, "食べ歩き、料理", "美食殿", 156, "M・A・O", 46, "ペコリーヌ（サマー）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, "エルフ", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "主を慕う、小さなガイド役", 11, 0, 1, 107601, 11, "瞑想、動植物の飼育", "美食殿", 140, "伊藤美来", 35, "コッコロ（サマー）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, "ヒューマン", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "お嬢さまのためにがんばるドジっ娘メイド", 15, 0, 9, 107701, 12, "ご奉仕", "サレンディア救護院", 154, "悠木碧", 43, "スズメ（サマー）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "獣人族", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "行き倒れの謎のネコミミ魔法使い", 14, 0, 1, 107801, 2, "猫と遊ぶ", "美食殿", 152, "立花理香", 39, "キャル（サマー）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "獣人族", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "弱きを助け強きをくじく猫娘", 19, 0, 12, 107901, 1, "猫とたわむれること", "メルクリウス財団", 158, "沼倉愛美", 48, "タマキ（サマー）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "ヒューマン", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "仕事も私事も効率優先な傭兵少女", 20, 0, 12, 108001, 11, "傭兵などのアルバイト", "メルクリウス財団", 163, "田所あずさ", 49, "ミフユ（サマー）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, "魔族", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占いが得意な霊能少女", 18, 0, 7, 108101, 22, "占い", "悪魔偽王国軍（ディアボロス）", 157, "大坪由佳", 42, "シノブ（ハロウィン）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, "魔族", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "プリン大好きゴースト娘", 14, 0, 7, 108201, 23, "プリンを食べること", "悪魔偽王国軍（ディアボロス）", 130, "雨宮天", 32, "ミヤコ（ハロウィン）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, "魔族", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ちょっとおませな恋に恋する女の子", 11, 0, 14, 108301, 3, "ファッション誌鑑賞、コスメ集め", "ルーセント学院", 120, "久野美咲", 22, "ミサキ（ハロウィン）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, "ヒューマン", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "人々を守るために歌う、唱喚士の少女", 17, 0, 4, 108401, 3, "各種楽器", "カルミナ", 163, "福原綾香", 46, "チカ（クリスマス）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, "ヒューマン", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "泣き虫で臆病な守ってあげたい女の子", 12, 0, 9, 108501, 9, "観劇、おままごと", "サレンディア救護院", 150, "植田佳奈", 40, "クルミ（クリスマス）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, "ヒューマン", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "ぷうきちといつも一緒！", 14, 0, 9, 108601, 10, "屋内でできる遊び", "サレンディア救護院", 148, "芹澤優", 38, "アヤネ（クリスマス）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "獣人族", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助けが大好き！　前向き格闘娘", 16, 0, 2, 108701, 27, "人助け、応援", "トゥインクルウィッシュ", 155, "東山奈央", 44, "ヒヨリ（ニューイヤー）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, "ヒューマン", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "戦闘のサポートが得意な、心優しい少女", 17, 0, 2, 108801, 5, "料理、人間観察", "トゥインクルウィッシュ", 158, "種田梨沙", 47, "ユイ（ニューイヤー）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, "魔族", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "クールで何事にも真っ直ぐな剣士", 18, 0, 2, 108901, 12, "読書、乗馬、お茶", "トゥインクルウィッシュ", 163, "早見沙織", 46, "レイ（ニューイヤー）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "魔族", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "運命の相手に一途すぎる乙女", 16, 0, 13, 109001, 30, "実験、裁縫、料理", "トワイライトキャラバン", 154, "橋本ちなみ", 43, "エリコ（バレンタイン）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, "ヒューマン", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "お姉ちゃんがお世話してあげるからねっ！", 18, 0, 3, 109101, 24, "家事全般", "ラビリンス", 168, "生天目仁美", 54, "シズル（バレンタイン）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, "ヒューマン", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", "英霊と契約を結んだマナリアの天才王女", 17, 0, "", 109201, 1, "読書", "？？？", 156, "日笠陽子", 55, "アン", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (2, "ヒューマン", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", "マナリア魔法学院の新入生", 16, 0, "", 109301, 4, "食べること、眠ること", "？？？", 144, "こやまきみこ", 45, "ルゥ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "半人半竜", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", "人を超越した力を有す心優しい竜姫", 17, 0, "", 109401, 3, "ピアノ", "？？？", 167, "福原綾香", 67, "グレア", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "ヒューマン", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "妄想大好き！　ほんとは照れ屋な女の子", 18, 0, 15, 109501, 19, "小説を読むこと", "ヴァイスフリューゲル　ランドソル支部", 157, "長妻樹里", 49, "クウカ（オーエド）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "ヒューマン", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "トーゴクの神秘、オシエテクダサイ！", 16, 0, 15, 109601, 31, "忍法開発", "ヴァイスフリューゲル　ランドソル支部", 163, "佐藤聡美", 51, "ニノン（オーエド）", "O");
