INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, "魔族", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "天真爛漫で人気者のカリスマモデル", 17, 0, 14, 110001, 10, "ファッション", "ルーセント学院", 167, "上坂すみれ", 48, "スズナ（サマー）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "魔族", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "多くの男性を魅了する無垢な女教師", 23, 0, 14, 110101, 14, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "ルーセント学院", 162, "伊藤静", 52, "イオ（サマー）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, "魔族", "", "ちょっとおませな恋に恋する女の子", 11, 0, 14, 110201, 3, "ファッション誌鑑賞、コスメ集め", "ルーセント学院", 120, "久野美咲", 22, "ミサキ（サマー）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, "エルフ", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "救護院を経営する優しい庶民派お嬢様", 17, 0, 9, 110301, 4, "経営、お茶会", "サレンディア救護院", 156, "堀江由衣", 43, "サレン（サマー）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "獣人族", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "男勝りで情に厚いワイルド娘", 17, 0, 10, 110401, 9, "お菓子作り", "自警団（カォン）", 168, "小松未可子", 54, "マコト（サマー）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "獣人族", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "いつでも「なんくるないさ～」な天然娘", 17, 0, 10, 110501, 7, "踊り、空手", "自警団（カォン）", 158, "高森奈津美", 53, "カオリ（サマー）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "獣人族", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "マホマホ王国のプリンセス", 16, 0, 10, 110601, 22, "空想、ぬいぐるみ集め", "自警団（カォン）", 155, "内田真礼", 42, "マホ（サマー）", "O");
