INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "獣人族", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "読書が趣味の病弱少女", 14, 0, 11, 112301, 3, "読書、お散歩", "牧場（エリザベスパーク）", 153, "小清水亜美", 40, "シオリ（マジカル）", "A");
