INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "魔族", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "前世を信じる中二病患者、「疾風の冥姫」", 17, 0, 13, 113201, 5, "小説執筆", "トワイライトキャラバン", 159, "髙野麻美", 45, "アンナ（サマー）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "魔族", "", "オタク全開な魔法少女", 18, 0, 13, 113301, 21, "読書、魔法", "トワイライトキャラバン", 166, "佳村はるか", 55, "ナナカ（サマー）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, "エルフ", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "みんなのために超能力を使う眠り姫", 17, 0, 6, 113401, 24, "妹と遊ぶこと、二度寝、昼寝、早寝", "フォレスティエ", 156, "大橋彩香", 46, "ハツネ（サマー）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "エルフ", "", "母性溢れる優しいみんなの「ミサト先生」", 21, 0, 6, 113501, 5, "絵本作り", "フォレスティエ", 165, "國府田マリ子", 54, "ミサト（サマー）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, "ヒューマン", "", "素顔を見せない冷静沈着な女性騎士", 25, 0, 8, 113601, 25, "格闘技、湯浴み", "王宮騎士団（NIGHTMARE）", 171, "川澄綾子", 50, "ジュン（サマー）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "魔族", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "甘え上手なみんなの人気者", 13, 0, 7, 113701, 22, "サックス", "悪魔偽王国軍（ディアボロス）", 150, "浅倉杏美", 42, "アカリ（エンジェル）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "魔族", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "人見知りであまのじゃくな女の子", 13, 0, 7, 113801, 22, "ゲーム全般", "悪魔偽王国軍（ディアボロス）", 150, "原紗友里", 40, "ヨリ（エンジェル）", "O");
