INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, "魔族", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "クールで何事にも真っ直ぐな剣士", 18, 0, 2, 114001, 12, "読書、乗馬、お茶", "トゥインクルウィッシュ", 163, "早見沙織", 46, "レイ（ハロウィン）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "獣人族", "", "ヒーローに憧れる騎士見習いの少女", 12, 0, 8, 114101, 25, "ヒーローごっこ", "王宮騎士団（NIGHTMARE）", 146, "下田麻美", 40, "マツリ（ハロウィン）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "ヒューマン", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "見た目も中身もお子ちゃまな異国の軍人", 17, 0, 15, 114201, 28, "お菓子屋通い", "ヴァイスフリューゲル　ランドソル支部", 140, "辻あゆみ", 33, "モニカ（マジカル）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "ヒューマン", "", "義理堅くてからかい好きな剣術少女", 13, 0, 8, 114301, 11, "剣術、年長者をからかう", "王宮騎士団（NIGHTMARE）", 149, "茅原実里", 43, "トモ（マジカル）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "ヒューマン", "この私とともにいる限り、\nお金に不自由はさせませんわ！", "一人前の商人を目指すパワフルお嬢様", 18, 0, 12, 114401, 12, "慈善事業", "メルクリウス財団", 157, "松嵜麗", 45, "アキノ（クリスマス）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, "エルフ", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "救護院を経営する優しい庶民派お嬢様", 17, 0, 9, 114501, 4, "経営、お茶会", "サレンディア救護院", 156, "堀江由衣", 43, "サレン（クリスマス）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "エルフ", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "純情でほっとけない大人の女性", 22, 0, 12, 114601, 16, "ウインドーショッピング", "メルクリウス財団", 164, "今井麻美", 55, "ユカリ（クリスマス）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "ヒューマン", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "さまよえる謎の少女", 16, 0, "", 114701, 11, "冒険、思い出話", "？？？", 148, "潘めぐみ", 40, "ムイミ（ニューイヤー）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "エルフ", "", "研究所に隠れ住む物静かなお姉さん", 24, 0, "", 115001, 24, "物真似、芸術鑑賞", "？？？", 149, "井口裕香", "??", "ネネカ（ニューイヤー）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, "エルフ", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "主を慕う、小さなガイド役", 11, 0, 1, 115501, 11, "瞑想、動植物の飼育", "美食殿", 140, "伊藤美来", 35, "コッコロ（儀装束）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, "ヒューマン", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "戦闘のサポートが得意な、心優しい少女", 17, 0, 2, 115601, 5, "料理、人間観察", "トゥインクルウィッシュ", 158, "種田梨沙", 47, "ユイ（儀装束）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "獣人族", "", "頭脳明晰な美少女名探偵", 15, 0, 10, 115701, 3, "読書、推理", "自警団（カォン）", 152, "水瀬いのり", 41, "カスミ（サマー）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "獣人族", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "乙女チックなもふもふアニマル", 17, 0, 11, 115801, 14, "毛繕い、お喋り", "牧場（エリザベスパーク）", 150, "徳井青空", 100, "リマ（シンデレラ）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "獣人族", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "男勝りで情に厚いワイルド娘", 17, 0, 10, 115901, 9, "お菓子作り", "自警団（カォン）", 168, "小松未可子", 54, "マコト（シンデレラ）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "獣人族", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "マホマホ王国のプリンセス", 16, 0, 10, 116001, 22, "空想、ぬいぐるみ集め", "自警団（カォン）", 155, "内田真礼", 42, "マホ（シンデレラ）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "エルフ", "", "ダウンタウン育ちのダウナー系エルフ", 17, 0, 16, 116201, 7, "ダーツ", "聖テレサ女学院（なかよし部）", 154, "種﨑敦美", 42, "クロエ（聖学祭）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "ヒューマン", "", "自由奔放ナチュラル無礼な現代っ子", 16, 0, 16, 116301, 15, "ダンス、カラオケ", "聖テレサ女学院（なかよし部）", 156, "佐倉綾音", 46, "チエル（聖学祭）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (2, "ヒューマン", "", "書庫に眠れる小さな賢人", 18, 0, 16, 116401, 28, "読書", "聖テレサ女学院（なかよし部）", 142, "小原好美", 36, "ユニ（聖学祭）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "ドラゴン族", "", "口が達者なヘタレドラゴン", 13, 0, 17, 116501, 29, "ゲーム", "ドラゴンズネスト", 145, "藤田茜", "???", "イノリ（タイムトラベル）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, "ドラゴン族", "", "拳で語る喧嘩屋ドラゴン少女", 16, 0, 17, 116601, 25, "格闘技", "ドラゴンズネスト", 156, "小市眞琴", "???", "カヤ（タイムトラベル）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, "エルフ", "", "「友達」に憧れる、エルフの森の女の子", 13, 0, 6, 116701, 6, "友達作りのイメトレ", "フォレスティエ", 158, "花澤香菜", 44, "アオイ（作業服）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "獣人族", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "弱きを助け強きをくじく猫娘", 19, 0, 12, 116801, 1, "猫とたわむれること", "メルクリウス財団", 158, "沼倉愛美", 48, "タマキ（作業服）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "ヒューマン", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "仕事も私事も効率優先な傭兵少女", 20, 0, 12, 116901, 11, "傭兵などのアルバイト", "メルクリウス財団", 163, "田所あずさ", 49, "ミフユ（作業服）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "魔族", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "運命の相手に一途すぎる乙女", 16, 0, 13, 117001, 30, "実験、裁縫、料理", "トワイライトキャラバン", 154, "橋本ちなみ", 43, "エリコ（サマー）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, "ヒューマン", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "お姉ちゃんがお世話してあげるからねっ！", 18, 0, 3, 117101, 24, "家事全般", "ラビリンス", 168, "生天目仁美", 54, "シズル（サマー）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, "ヒューマン", "", "歌って踊れる大人気アイドル", 17, 0, 4, 117201, 24, "舞台鑑賞、ダンス", "カルミナ", 157, "日笠陽子", 40, "ノゾミ（サマー）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, "ヒューマン", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "人々を守るために歌う、唱喚士の少女", 17, 0, 4, 117301, 3, "各種楽器", "カルミナ", 163, "福原綾香", 46, "チカ（サマー）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "ヒューマン", "", "ファッション大好きなキュートガール", 14, 0, 4, 117401, 7, "裁縫", "カルミナ", 153, "木戸衣吹", 45, "ツムギ（サマー）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "ヒューマン", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "実験が趣味の危険な科学者", 27, 0, 13, 117501, 7, "研究、実験", "トワイライトキャラバン", 166, "三石琴乃", 53, "ミツキ（オーエド）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, "エルフ", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "ボクは誰よりも美しい", 14, 0, 15, 117601, 10, "鏡で自分を見ること", "ヴァイスフリューゲル　ランドソル支部", 150, "大空直美", 40, "ユキ（オーエド）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "獣人族", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "いつでも「なんくるないさ～」な天然娘", 17, 0, 10, 117701, 7, "踊り、空手", "自警団（カォン）", 158, "高森奈津美", 53, "カオリ（ハロウィン）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "ヒューマン", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "トーゴクの神秘、オシエテクダサイ！", 16, 0, 15, 117801, 31, "忍法開発", "ヴァイスフリューゲル　ランドソル支部", 163, "佐藤聡美", 51, "ニノン（ハロウィン）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, "魔族", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "天真爛漫で人気者のカリスマモデル", 17, 0, 14, 117901, 10, "ファッション", "ルーセント学院", 167, "上坂すみれ", 48, "スズナ（ハロウィン）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "ヒューマン", "", "忠義に目覚めた女商人", 26, 0, 18, 118001, 19, "お金を数えること、悪だくみ", "リッチモンド商工会", 160, "Lynn", 57, "クレジッタ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, "魔族", "", "静寂を求め歌う陰気少女", 20, 0, 19, 118101, 28, "歌、読書、詩を書くこと", "レイジ・レギオン", 165, "原田彩楓", 53, "ランファ", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "ヒューマン", "", "明朗快活、なれど破滅に流るる溌溂少女", 16, 0, 19, 118201, 2, "特に無し", "レイジ・レギオン", 159, "鬼頭明里", "??", "ミソラ", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "ヒューマン", "", "【ギルド管理協会】職員の親切なお姉さん", 24, 0, "", 118501, 12, "書類仕事、散歩、ボードゲーム", "？？？", 152, "洲崎綾", 43, "カリン", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("?", "？？？", "", "幻霧に戯れる悪戯好きなガイド妖精", "??", 0, "", 118601, "?", "悪戯をすること", "？？？", "???", "相坂優歌", "???", "ネビア", "?");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "魔族", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "多くの男性を魅了する無垢な女教師", 23, 0, 14, 119001, 14, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "ルーセント学院", 162, "伊藤静", 52, "イオ（ノワール）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "ヒューマン", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "妄想大好き！　ほんとは照れ屋な女の子", 18, 0, 15, 119101, 19, "小説を読むこと", "ヴァイスフリューゲル　ランドソル支部", 157, "長妻樹里", 49, "クウカ（ノワール）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "ヒューマン", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "みんなを笑顔にするお笑い牧場主", 20, 0, 11, 119201, 3, "漫才", "牧場（エリザベスパーク）", 142, "新田恵海", 35, "マヒル（クリスマス）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "ヒューマン", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "人懐っこくてマシンガントークな妹系少女", 15, 0, 3, 119301, 25, "お裁縫", "ラビリンス", 156, "阿澄佳奈", 44, "リノ（クリスマス）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, "魔族", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "プリン大好きゴースト娘", 14, 0, 7, 119901, 23, "プリンを食べること", "悪魔偽王国軍（ディアボロス）", 130, "雨宮天", 32, "ミヤコ（クリスマス）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, "ヒューマン", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "お姉ちゃんがお世話してあげるからねっ！", 18, 0, 3, 120001, 24, "家事全般", "ラビリンス", 168, "生天目仁美", 54, "シズル（ノワール）", "O");
