INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, "ヒューマン", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "泣き虫で臆病な守ってあげたい女の子", 12, 0, 9, 121301, 9, "観劇、おままごと", "サレンディア救護院", 150, "植田佳奈", 40, "クルミ（ステージ）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, "魔族", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ちょっとおませな恋に恋する女の子", 11, 0, 14, 121401, 3, "ファッション誌鑑賞、コスメ集め", "ルーセント学院", 120, "久野美咲", 22, "ミサキ（ステージ）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, "エルフ", "", "どこまでも一途に慕う、純情乙女", 16, 0, 15, 121501, 7, "観察", "ヴァイスフリューゲル　ランドソル支部", 155, "大関英里", 43, "アユミ（怪盗）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "ドラゴン族", "", "口が達者なヘタレドラゴン", 13, 0, 17, 121601, 29, "ゲーム", "ドラゴンズネスト", 145, "藤田茜", "???", "イノリ（怪盗）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "魔族", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "前世を信じる中二病患者、「疾風の冥姫」", 17, 0, 13, 121901, 5, "小説執筆", "トワイライトキャラバン", 159, "髙野麻美", 45, "アンナ（パイレーツ）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, "魔族", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占いが得意な霊能少女", 18, 0, 7, 122001, 22, "占い", "悪魔偽王国軍（ディアボロス）", 157, "大坪由佳", 42, "シノブ（パイレーツ）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, "エルフ", "", "「友達」に憧れる、エルフの森の女の子", 13, 0, 6, 122101, 6, "友達作りのイメトレ", "フォレスティエ", 158, "花澤香菜", 44, "アオイ（キャンプ）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "エルフ", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "純情でほっとけない大人の女性", 22, 0, 12, 122201, 16, "ウインドーショッピング", "メルクリウス財団", 164, "今井麻美", 55, "ユカリ（キャンプ）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, "魔族", "", "けんぞくのご主人様", "??", 0, "", 122301, 6, "お散歩、お料理", "？？？", 149, "釘宮理恵", 41, "ヴァンピィ", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "獣人族", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助けが大好き！　前向き格闘娘", 16, 0, 2, 122401, 27, "人助け、応援", "トゥインクルウィッシュ", 155, "東山奈央", 44, "ヒヨリ（サマー）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, "魔族", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "クールで何事にも真っ直ぐな剣士", 18, 0, 2, 122501, 12, "読書、乗馬、お茶", "トゥインクルウィッシュ", 163, "早見沙織", 46, "レイ（サマー）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, "ヒューマン", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "戦闘のサポートが得意な、心優しい少女", 17, 0, 2, 122601, 5, "料理、人間観察", "トゥインクルウィッシュ", 158, "種田梨沙", 47, "ユイ（サマー）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (2, "エルフ", "", "礼儀正しくしっかり者のちびっ子優等生", 8, 0, 5, 122701, 2, "お勉強", "リトルリリカル", 118, "小倉唯", 21, "キョウカ（サマー）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "ヒューマン", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "探検好きのイタズラっ子", 9, 0, 5, 122801, 10, "いたずら、探検", "リトルリリカル", 128, "諸星すみれ", 27, "ミソギ（サマー）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, "獣人族", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "お歌もにんじんも、ウサギさんも大好き♪", 10, 0, 5, 122901, 3, "かわいいもの集め", "リトルリリカル", 117, "日高里菜", 21, "ミミ（サマー）", "O");
