INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "魔族", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "甘え上手なみんなの人気者", 13, 0, 7, 124001, 22, "サックス", "悪魔偽王国軍（ディアボロス）", 150, "浅倉杏美", 42, "アカリ（クリスマス）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "魔族", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "人見知りであまのじゃくな女の子", 13, 0, 7, 124101, 22, "ゲーム全般", "悪魔偽王国軍（ディアボロス）", 150, "原紗友里", 40, "ヨリ（クリスマス）", "O");
