INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "ヒューマン", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "実験が趣味の危険な科学者", 27, 0, 13, 124701, 7, "研究、実験", "トワイライトキャラバン", 166, "三石琴乃", 53, "ミツキ（ニューイヤー）", "A");
