INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "ヒューマン", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "さまよえる謎の少女", 16, 0, "", 125001, 11, "冒険、思い出話", "？？？", 148, "潘めぐみ", 40, "ムイミ（リベレイター）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "獣人族", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "弱きを助け強きをくじく猫娘", 19, 0, 12, 125101, 1, "猫とたわむれること", "メルクリウス財団", 158, "沼倉愛美", 48, "タマキ（カフェ）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "ヒューマン", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "見た目も中身もお子ちゃまな異国の軍人", 17, 0, 15, 125201, 28, "お菓子屋通い", "ヴァイスフリューゲル　ランドソル支部", 140, "辻あゆみ", 33, "モニカ（カフェ）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, "エルフ", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "主を慕う、小さなガイド役", 11, 0, 1, 125301, 11, "瞑想、動植物の飼育", "美食殿", 140, "伊藤美来", 35, "コッコロ（レンジャー）", "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "獣人族", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "読書が趣味の病弱少女", 14, 0, 11, 125401, 3, "読書、お散歩", "牧場（エリザベスパーク）", 153, "小清水亜美", 40, "シオリ（レンジャー）", "A");
