INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, "エルフ", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "純情でほっとけない大人の女性", 22, 0, 12, 126801, 16, "ウインドーショッピング", "メルクリウス財団", 164, "今井麻美", 55, "ユカリ（サマー）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, "魔族", "", "静寂を求め歌う陰気少女", 20, 0, 19, 126901, 28, "歌、読書、詩を書くこと", "レイジ・レギオン", 165, "原田彩楓", 53, "ランファ（サマー）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, "ヒューマン", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "妄想大好き！　ほんとは照れ屋な女の子", 18, 0, 15, 127001, 19, "小説を読むこと", "ヴァイスフリューゲル　ランドソル支部", 157, "長妻樹里", 49, "クウカ（サマー）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, "魔族", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占いが得意な霊能少女", 18, 0, 7, 127101, 22, "占い", "悪魔偽王国軍（ディアボロス）", 157, "大坪由佳", 42, "シノブ（サマー）", "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, "獣人族", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "行き倒れの謎のネコミミ魔法使い", 14, 0, 1, 127201, 2, "猫と遊ぶ", "美食殿", 152, "立花理香", 39, "キャル（編入生）", "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, "魔族", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "天真爛漫で人気者のカリスマモデル", 17, 0, 14, 127301, 10, "ファッション", "ルーセント学院", 167, "上坂すみれ", 48, "スズナ（編入生）", "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, "エルフ", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "救護院を経営する優しい庶民派お嬢様", 17, 0, 9, 127501, 4, "経営、お茶会", "サレンディア救護院", 156, "堀江由衣", 43, "サレン（サラサリア）", "A");
