INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (8, "獣人族", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助けが大好き！　前向き格闘娘", 16, 0, 2, 128701, 27, "人助け、応援", "トゥインクルウィッシュ", 155, "東山奈央", 44, "ヒヨリ（アストラル）", "A");
