INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, "ヒューマン", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "戦闘のサポートが得意な、心優しい少女", 17, 0, 2, 136401, 5, "料理、人間観察", "トゥインクルウィッシュ", 158, "種田梨沙", 47, "ユイ（クリスマス）", "O");
